<?php
require_once __DIR__ . '/admin_guard.php';

/* Admin reporting workspace. All optional filters are validated before use. */
function ar_escape($value): string {
    return htmlspecialchars((string)($value ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}
function ar_scalar(mysqli $conn, string $sql, string $types = '', array $params = []): float {
    $stmt = mysqli_prepare($conn, $sql);
    if (!$stmt) return 0;
    if ($types !== '') { $bind = [$stmt, $types]; foreach ($params as &$param) $bind[] = &$param; call_user_func_array('mysqli_stmt_bind_param', $bind); unset($param); }
    if (!mysqli_stmt_execute($stmt)) { mysqli_stmt_close($stmt); return 0; }
    $result = mysqli_stmt_get_result($stmt);
    $row = $result ? mysqli_fetch_row($result) : null;
    if ($result) mysqli_free_result($result);
    mysqli_stmt_close($stmt);
    return (float)($row[0] ?? 0);
}
function ar_rows(mysqli $conn, string $sql, string $types = '', array $params = []): array {
    $stmt = mysqli_prepare($conn, $sql);
    if (!$stmt) return [];
    if ($types !== '') { $bind = [$stmt, $types]; foreach ($params as &$param) $bind[] = &$param; call_user_func_array('mysqli_stmt_bind_param', $bind); unset($param); }
    if (!mysqli_stmt_execute($stmt)) { mysqli_stmt_close($stmt); return []; }
    $result = mysqli_stmt_get_result($stmt);
    $rows = [];
    if ($result) { while ($row = mysqli_fetch_assoc($result)) $rows[] = $row; mysqli_free_result($result); }
    mysqli_stmt_close($stmt);
    return $rows;
}
function ar_date(string $value): string {
    if ($value === '') return '';
    $dt = DateTime::createFromFormat('!Y-m-d', $value);
    return $dt && $dt->format('Y-m-d') === $value ? $value : '';
}
function ar_date_filter(string $column, string $fromStart, string $toEnd): array {
    $parts = []; $types = ''; $params = [];
    if ($fromStart !== '') { $parts[] = $column . ' >= ?'; $types .= 's'; $params[] = $fromStart; }
    if ($toEnd !== '') { $parts[] = $column . ' <= ?'; $types .= 's'; $params[] = $toEnd; }
    return [$parts ? ' AND ' . implode(' AND ', $parts) : '', $types, $params];
}
function ar_selected(string $value, array $allowed, string $fallback = 'All'): string {
    return in_array($value, $allowed, true) ? $value : $fallback;
}
function ar_money($value): string { return '৳' . number_format((float)$value, 2); }

$from = ar_date(trim((string)($_GET['from'] ?? '')));
$to = ar_date(trim((string)($_GET['to'] ?? '')));
if ($from !== '' && $to !== '' && $from > $to) { [$from, $to] = [$to, $from]; }
$role = ar_selected((string)($_GET['role'] ?? 'All'), ['All','User','Admin','Manager','Authenticator']);
$accountStatus = ar_selected((string)($_GET['account_status'] ?? 'All'), ['All','Active','Inactive','Suspended']);
$profileVerification = ar_selected((string)($_GET['profile_verification'] ?? 'All'), ['All','Pending','Verified','Rejected','No profile']);
$bookingStatus = ar_selected((string)($_GET['booking_status'] ?? 'All'), ['All','Pending','Confirmed','Completed','Cancelled']);
$staffRole = ar_selected((string)($_GET['staff_role'] ?? 'All'), ['All','Manager','Authenticator','Admin']);
$search = trim(substr((string)($_GET['q'] ?? ''), 0, 100));
$limit = (int)($_GET['limit'] ?? 50);
if (!in_array($limit, [25,50,100,200], true)) $limit = 50;
$validSections = ['overview','accounts','bookings','manager_activity','verification','staff_messages'];
$sections = isset($_GET['sections']) && is_array($_GET['sections']) ? array_values(array_intersect($validSections, array_map('strval', $_GET['sections']))) : $validSections;

$fromStart = $from !== '' ? $from . ' 00:00:00' : '';
$toEnd = $to !== '' ? $to . ' 23:59:59' : '';
[$usersDateSql, $usersDateTypes, $usersDateParams] = ar_date_filter('created_at', $fromStart, $toEnd);
[$bookingsDateSql, $bookingsDateTypes, $bookingsDateParams] = ar_date_filter('booking_date', $fromStart, $toEnd);
[$managerDateSql, $managerDateTypes, $managerDateParams] = ar_date_filter('created_at', $fromStart, $toEnd);
[$verifyDateSql, $verifyDateTypes, $verifyDateParams] = ar_date_filter('action_at', $fromStart, $toEnd);
[$messagesDateSql, $messagesDateTypes, $messagesDateParams] = ar_date_filter('created_at', $fromStart, $toEnd);
$dateLabel = $from !== '' && $to !== '' ? $from . ' to ' . $to : ($from !== '' ? 'From ' . $from : ($to !== '' ? 'Through ' . $to : 'All dates'));

// Current snapshot cards and selected-period activity totals.
$metrics = [
    ['Booking value in period', ar_scalar($conn, 'SELECT COALESCE(SUM(total_price),0) FROM bookings WHERE admin_removed=0' . $bookingsDateSql, $bookingsDateTypes, $bookingsDateParams), 'money'],
    ['Completed booking value', ar_scalar($conn, "SELECT COALESCE(SUM(total_price),0) FROM bookings WHERE admin_removed=0 AND booking_status='Completed'" . $bookingsDateSql, $bookingsDateTypes, $bookingsDateParams), 'money'],
    ['Total booking of all time', ar_scalar($conn, 'SELECT COUNT(*) FROM bookings WHERE admin_removed=0'), 'snapshot'],
    ['Total accounts', ar_scalar($conn, 'SELECT COUNT(*) FROM users'), 'snapshot'],
    ['Active accounts', ar_scalar($conn, "SELECT COUNT(*) FROM users WHERE account_status='Active'"), 'snapshot'],
    ['Suspended accounts', ar_scalar($conn, "SELECT COUNT(*) FROM users WHERE account_status='Suspended'"), 'snapshot'],
    ['Users registered in period', ar_scalar($conn, 'SELECT COUNT(*) FROM users WHERE 1=1' . $usersDateSql, $usersDateTypes, $usersDateParams), 'period'],
    ['User profiles', ar_scalar($conn, 'SELECT COUNT(*) FROM user_profiles'), 'snapshot'],
    ['Pending verification', ar_scalar($conn, "SELECT COUNT(*) FROM user_profiles WHERE verification_status='Pending'"), 'snapshot'],
    ['Verified profiles', ar_scalar($conn, "SELECT COUNT(*) FROM user_profiles WHERE verification_status='Verified'"), 'snapshot'],
    ['Rejected profiles', ar_scalar($conn, "SELECT COUNT(*) FROM user_profiles WHERE verification_status='Rejected'"), 'snapshot'],
    ['Bookings in period', ar_scalar($conn, 'SELECT COUNT(*) FROM bookings WHERE admin_removed=0' . $bookingsDateSql, $bookingsDateTypes, $bookingsDateParams), 'period'],
    ['Pending bookings', ar_scalar($conn, "SELECT COUNT(*) FROM bookings WHERE admin_removed=0 AND booking_status='Pending'" . $bookingsDateSql, $bookingsDateTypes, $bookingsDateParams), 'period'],
    ['Confirmed bookings', ar_scalar($conn, "SELECT COUNT(*) FROM bookings WHERE admin_removed=0 AND booking_status='Confirmed'" . $bookingsDateSql, $bookingsDateTypes, $bookingsDateParams), 'period'],
    ['Completed bookings', ar_scalar($conn, "SELECT COUNT(*) FROM bookings WHERE admin_removed=0 AND booking_status='Completed'" . $bookingsDateSql, $bookingsDateTypes, $bookingsDateParams), 'period'],
    ['Cancelled bookings', ar_scalar($conn, "SELECT COUNT(*) FROM bookings WHERE admin_removed=0 AND booking_status='Cancelled'" . $bookingsDateSql, $bookingsDateTypes, $bookingsDateParams), 'period'],
    ['Service providers', ar_scalar($conn, 'SELECT COUNT(*) FROM service_providers'), 'snapshot'],
    ['Manager actions in period', ar_scalar($conn, 'SELECT COUNT(*) FROM manager_activity_log WHERE 1=1' . $managerDateSql, $managerDateTypes, $managerDateParams), 'period'],
    ['Verification actions in period', ar_scalar($conn, 'SELECT COUNT(*) FROM verification_logs WHERE 1=1' . $verifyDateSql, $verifyDateTypes, $verifyDateParams), 'period'],
    ['Unread staff messages', ar_scalar($conn, "SELECT COUNT(*) FROM staff_admin_messages WHERE recipient_role='Admin' AND status='Unread'"), 'snapshot'],
];

// Account report filters: registration period, role, current status and optional keyword.
$userWhere = ['1=1']; $userTypes = ''; $userParams = []; if ($fromStart !== '') { $userWhere[] = 'u.created_at >= ?'; $userTypes .= 's'; $userParams[] = $fromStart; } if ($toEnd !== '') { $userWhere[] = 'u.created_at <= ?'; $userTypes .= 's'; $userParams[] = $toEnd; }
if ($role !== 'All') { $userWhere[] = 'u.role=?'; $userTypes .= 's'; $userParams[] = $role; }
if ($accountStatus !== 'All') { $userWhere[] = 'u.account_status=?'; $userTypes .= 's'; $userParams[] = $accountStatus; }
if ($profileVerification === 'No profile') { $userWhere[] = 'up.profile_id IS NULL'; } elseif ($profileVerification !== 'All') { $userWhere[] = 'up.verification_status=?'; $userTypes .= 's'; $userParams[] = $profileVerification; }
if ($search !== '') {
    $userWhere[] = "(u.first_name LIKE ? OR u.last_name LIKE ? OR CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,'')) LIKE ? OR u.email LIKE ? OR u.mobile LIKE ? OR CAST(u.user_id AS CHAR) LIKE ?)";
    $like = '%' . $search . '%'; $userTypes .= 'ssssss'; array_push($userParams, $like, $like, $like, $like, $like, $like);
}
$userRows = ar_rows($conn, 'SELECT u.user_id,u.first_name,u.last_name,u.email,u.mobile,u.role,u.account_status,u.created_at,up.profile_id,up.verification_status FROM users u LEFT JOIN user_profiles up ON up.user_id=u.user_id WHERE ' . implode(' AND ', $userWhere) . ' ORDER BY u.created_at DESC,u.user_id DESC LIMIT ' . $limit, $userTypes, $userParams);

$bookingWhere = ['b.admin_removed=0']; $bookingTypes = ''; $bookingParams = []; if ($fromStart !== '') { $bookingWhere[] = 'b.booking_date >= ?'; $bookingTypes .= 's'; $bookingParams[] = $fromStart; } if ($toEnd !== '') { $bookingWhere[] = 'b.booking_date <= ?'; $bookingTypes .= 's'; $bookingParams[] = $toEnd; }
if ($bookingStatus !== 'All') { $bookingWhere[] = 'b.booking_status=?'; $bookingTypes .= 's'; $bookingParams[] = $bookingStatus; }
if ($search !== '') { $bookingWhere[] = "(CAST(b.booking_id AS CHAR) LIKE ? OR u.first_name LIKE ? OR u.last_name LIKE ? OR CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,'')) LIKE ? OR u.email LIKE ?)"; $like = '%' . $search . '%'; $bookingTypes .= 'sssss'; array_push($bookingParams, $like, $like, $like, $like, $like); }
$bookingRows = ar_rows($conn, 'SELECT b.booking_id,b.booking_date,b.booking_status,b.total_price,b.user_id,b.manager_id,CONCAT(COALESCE(u.first_name,\'\'),\' \',COALESCE(u.last_name,\'\')) AS customer_name,u.email,CONCAT(COALESCE(m.first_name,\'\'),\' \',COALESCE(m.last_name,\'\')) AS manager_name FROM bookings b LEFT JOIN users u ON u.user_id=b.user_id LEFT JOIN users m ON m.user_id=b.manager_id WHERE ' . implode(' AND ', $bookingWhere) . ' ORDER BY b.booking_date DESC,b.booking_id DESC LIMIT ' . $limit, $bookingTypes, $bookingParams);

$managerWhere = ['1=1']; $managerTypes = ''; $managerParams = []; if ($fromStart !== '') { $managerWhere[] = 'mal.created_at >= ?'; $managerTypes .= 's'; $managerParams[] = $fromStart; } if ($toEnd !== '') { $managerWhere[] = 'mal.created_at <= ?'; $managerTypes .= 's'; $managerParams[] = $toEnd; }
if ($staffRole === 'Authenticator' || $staffRole === 'Admin') { $managerWhere[] = '1=0'; }
if ($search !== '') { $managerWhere[] = '(mal.manager_name LIKE ? OR mal.action_type LIKE ? OR mal.details LIKE ? OR CAST(mal.booking_id AS CHAR) LIKE ?)'; $like = '%' . $search . '%'; $managerTypes .= 'ssss'; array_push($managerParams, $like, $like, $like, $like); }
$managerRows = ar_rows($conn, 'SELECT mal.activity_id,mal.manager_name,mal.action_type,mal.booking_id,mal.provider_id,mal.amount,mal.details,mal.created_at FROM manager_activity_log mal WHERE ' . implode(' AND ', $managerWhere) . ' ORDER BY mal.created_at DESC,mal.activity_id DESC LIMIT ' . $limit, $managerTypes, $managerParams);

$verifyWhere = ['1=1']; $verifyTypes = ''; $verifyParams = []; if ($fromStart !== '') { $verifyWhere[] = 'vl.action_at >= ?'; $verifyTypes .= 's'; $verifyParams[] = $fromStart; } if ($toEnd !== '') { $verifyWhere[] = 'vl.action_at <= ?'; $verifyTypes .= 's'; $verifyParams[] = $toEnd; }
if ($staffRole === 'Manager') $verifyWhere[] = '1=0';
if ($profileVerification === 'No profile') { $verifyWhere[] = 'up.profile_id IS NULL'; } elseif ($profileVerification !== 'All') { $verifyWhere[] = 'up.verification_status=?'; $verifyTypes .= 's'; $verifyParams[] = $profileVerification; }
if ($search !== '') { $verifyWhere[] = "(u.first_name LIKE ? OR u.last_name LIKE ? OR CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,'')) LIKE ? OR vl.action LIKE ? OR vl.remarks LIKE ? OR CAST(vl.profile_id AS CHAR) LIKE ?)"; $like = '%' . $search . '%'; $verifyTypes .= 'ssssss'; array_push($verifyParams, $like, $like, $like, $like, $like, $like); }
$verifyRows = ar_rows($conn, 'SELECT vl.log_id,vl.action_at,vl.profile_id,vl.action,vl.remarks,vl.authenticator_id,CONCAT(COALESCE(u.first_name,\'\'),\' \',COALESCE(u.last_name,\'\')) AS authenticator_name FROM verification_logs vl LEFT JOIN users u ON u.user_id=vl.authenticator_id LEFT JOIN user_profiles up ON up.profile_id=vl.profile_id WHERE ' . implode(' AND ', $verifyWhere) . ' ORDER BY vl.action_at DESC,vl.log_id DESC LIMIT ' . $limit, $verifyTypes, $verifyParams);

$messageWhere = ['(sam.sender_role<>\'Admin\' OR sam.recipient_role=\'Admin\')']; $messageTypes = ''; $messageParams = []; if ($fromStart !== '') { $messageWhere[] = 'sam.created_at >= ?'; $messageTypes .= 's'; $messageParams[] = $fromStart; } if ($toEnd !== '') { $messageWhere[] = 'sam.created_at <= ?'; $messageTypes .= 's'; $messageParams[] = $toEnd; }
if ($staffRole !== 'All') { $messageWhere[] = '(sam.sender_role=? OR sam.recipient_role=?)'; $messageTypes .= 'ss'; array_push($messageParams, $staffRole, $staffRole); }
if ($search !== '') { $messageWhere[] = "(sam.message LIKE ? OR sam.sender_role LIKE ? OR sam.recipient_role LIKE ? OR CONCAT(COALESCE(s.first_name,''),' ',COALESCE(s.last_name,'')) LIKE ? OR CONCAT(COALESCE(r.first_name,''),' ',COALESCE(r.last_name,'')) LIKE ?)"; $like = '%' . $search . '%'; $messageTypes .= 'sssss'; array_push($messageParams, $like, $like, $like, $like, $like); }
$messageRows = ar_rows($conn, 'SELECT sam.message_id,sam.sender_role,sam.recipient_role,sam.message,sam.status,sam.created_at,sam.read_at,CONCAT(COALESCE(s.first_name,\'\'),\' \',COALESCE(s.last_name,\'\')) AS sender_name,CONCAT(COALESCE(r.first_name,\'\'),\' \',COALESCE(r.last_name,\'\')) AS recipient_name FROM staff_admin_messages sam LEFT JOIN users s ON s.user_id=sam.sender_id LEFT JOIN users r ON r.user_id=sam.recipient_id WHERE ' . implode(' AND ', $messageWhere) . ' ORDER BY sam.created_at DESC,sam.message_id DESC LIMIT ' . $limit, $messageTypes, $messageParams);

// CSV export honors the selected report section and the same filters.
if (isset($_GET['export']) && $_GET['export'] === 'csv') {
    $section = ar_selected((string)($_GET['export_section'] ?? 'accounts'), ['accounts','bookings','manager_activity','verification','staff_messages'], 'accounts');
    $datasets = [
        'accounts' => ['Accounts', $userRows], 'bookings' => ['Bookings', $bookingRows],
        'manager_activity' => ['Manager Activity', $managerRows], 'verification' => ['Verification Activity', $verifyRows],
        'staff_messages' => ['Staff Messages', $messageRows],
    ];
    [$filename, $data] = $datasets[$section];
    header('Content-Type: text/csv; charset=UTF-8');
    header('Content-Disposition: attachment; filename="admin_' . strtolower(str_replace(' ', '_', $filename)) . '_' . $from . '_to_' . $to . '.csv"');
    echo "\xEF\xBB\xBF";
    $out = fopen('php://output', 'w');
    if ($data) { fputcsv($out, array_keys($data[0])); foreach ($data as $record) fputcsv($out, array_values($record)); }
    else { fputcsv($out, ['No records found']); }
    fclose($out); exit;
}

$sectionNames = ['overview'=>'Executive overview','accounts'=>'Account & profile register','bookings'=>'Booking & value register','manager_activity'=>'Manager activity audit','verification'=>'Authenticator verification audit','staff_messages'=>'Staff communication audit'];
$filterQuery = $_GET; unset($filterQuery['export'], $filterQuery['export_section']);
$csvUrl = function(string $section) use ($filterQuery): string { $q = $filterQuery; $q['export'] = 'csv'; $q['export_section'] = $section; return 'reports.php?' . http_build_query($q); };
?>
