rid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.field{min-width:0}.field label{display:block;font-size:11px;color:var(--muted);font-weight:800;margin:0 0 5px}.field input,.field select{width:100%;min-width:0;border:1px solid #cdded9;border-radius:9px;background:#fff;color:var(--ink);font:inherit;padding:10px 11px;min-height:41px}.field.search{grid-column:span 2}.filter-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.checks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.check{display:flex;gap:9px;align-items:flex-start;border:1px solid var(--line);border-radius:10px;padding:10px;background:#fbfdfc;min-width:0}.check input{margin-top:4px;accent-color:var(--accent)}.check strong{display:block;font-size:12px}.check small{display:block;color:var(--muted);font-size:11px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.metric{position:relative;overflow:hidden;padding:15px;border:1px solid var(--line);border-radius:13px;background:linear-gradient(145deg,#fff,#f8fcfb);min-width:0;break-inside:avoid}.metric:before{content:"";position:absolute;right:-20px;top:-24px;width:70px;height:70px;border-radius:50%;background:#d8f0e9;opacity:.65}.metric span{display:block;position:relative;color:var(--muted);font-size:11px;font-weight:750}.metric strong{display:block;position:relative;margin-top:7px;font-size:clamp(20px,2vw,28px);line-height:1.2;overflow-wrap:anywhere;letter-spacing:-.03em}.metric small{display:block;color:var(--muted);font-size:10px;margin-top:5px}.table-wrap{width:100%;max-width:100%;overflow:auto;border:1px solid #e3ece9;border-radius:11px;-webkit-overflow-scrolling:touch;overscroll-behavior:auto}table{width:100%;min-width:780px;border-collapse:separate;border-spacing:0;font-size:12px}th,td{text-align:left;vertical-align:top;padding:10px 10px;border-bottom:1px solid #e8efed;overflow-wrap:anywhere;max-width:360px}th{position:sticky;top:0;z-index:1;color:#4d6964;font-size:10px;letter-spacing:.04em;text-transform:uppercase;background:#f0f8f5;white-space:nowrap}td{white-space:pre-wrap}th:first-child,td:first-child{width:48px;min-width:48px;color:#55716c;font-variant-numeric:tabular-nums}tbody tr:nth-child(even){background:#fbfdfc}tbody tr:hover{background:#f1faf7}.pill{display:inline-block;padding:3px 8px;border-radius:99px;background:#e6f5f0;color:#16675d;font-weight:800;font-size:10px;white-space:nowrap}.pill.warn{background:#fff2d8;color:#8a5b0b}.pill.bad{background:#ffebeb;color:#a33636}.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:11px}.section-count{font-size:11px;color:var(--muted);font-weight:700}.section-title{display:flex;align-items:center;gap:9px}.section-dot{width:9px;height:9px;background:var(--accent);border-radius:3px;display:inline-block}.table-actions{display:flex;gap:7px;flex-wrap:wrap}.muted{color:var(--muted)}.footnote{font-size:11px;color:var(--muted);margin:12px 0 0}.no-print{}@media(max-width:1050px){.filters{grid-template-columns:repeat(3,minmax(0,1fr))}.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:650px){.wrap{padding:0 10px 24px;margin:10px auto}.hero{border-radius:15px;padding:20px 16px}.hero-inner{align-items:flex-start}.actions{width:100%}.actions .btn{flex:1}.panel{padding:13px;border-radius:13px;margin-bottom:12px}.filters{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.field.search{grid-column:span 2}.metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.metric{padding:11px}.metric strong{font-size:21px}.checks{grid-template-columns:repeat(2,minmax(0,1fr))}.btn{padding:10px 11px}.panel-heading{margin-bottom:12px}}@media(max-width:380px){.filters,.checks{grid-template-columns:1fr}.field.search{grid-column:span 1}.metrics{grid-template-columns:1fr 1fr}.hero h1{font-size:23px}}
/* Reporting layout polish: screen hierarchy and print/PDF readability. */
.section-title{display:flex;align-items:center;gap:9px}.section-dot{display:inline-block;flex:0 0 9px;width:9px;height:9px;border-radius:50%;background:linear-gradient(135deg,#0f766e,#53b7a5);box-shadow:0 0 0 4px #e5f5f0}.section-count{display:inline-flex;align-items:center;gap:5px;padding:6px 10px;border:1px solid #cfe5de;border-radius:999px;background:#f0faf6;color:#17665d;font-size:11px;font-weight:800;white-space:nowrap}.metrics .metric:nth-child(-n+3){background:linear-gradient(145deg,#f0fbf7,#fff);border-color:#b9ddd2}.metrics .metric:nth-child(1):before,.metrics .metric:nth-child(2):before,.metrics .metric:nth-child(3):before{background:#bde8d8}.metrics .metric:nth-child(-n+3) strong{color:#0b6258}.table-wrap{box-shadow:0 3px 12px rgba(21,57,52,.035)}table tbody tr:nth-child(even){background:#fbfdfc}table tbody tr:hover{background:#f0faf6}table th:first-child,table td:first-child{width:52px;min-width:52px;text-align:center;color:#54716b;font-variant-numeric:tabular-nums}table td strong{color:#125f56}.empty{border:1px dashed #c8ddd6;border-radius:12px;padding:18px;background:#f8fcfa;color:#687d79;text-align:center}.footnote{color:#637974}.field input:focus,.field select:focus{outline:3px solid #c7eee2;outline-offset:1px;border-color:#0f766e}.check:has(input:checked){border-color:#9fd2c3;background:#f1faf6}.panel-heading .sub{max-width:820px}
