<body><main class="wrap">
<header class="hero"><div class="hero-inner"><div><div class="eyebrow">Smart Matrimony · Admin workspace</div><h1>Reports &amp; Analytics</h1><p>Detailed platform overview, account register, booking value and staff audit trails.</p><p class="sub" style="color:#e0f4ef">Reporting period: <?= ar_escape($dateLabel) ?> · Generated <?= date('d M Y, h:i A') ?></p></div><div class="actions no-print"><button class="btn" type="button" onclick="window.print()">▤ Print / Save PDF</button><a class="btn light" href="dashboard.php">← Admin Dashboard</a></div></div></header>
<form method="get" class="panel no-print" id="reportFilters"><div class="panel-heading"><div><h2>Report controls</h2><p class="sub">Choose a date range, narrow the records and select exactly which sections should appear in the PDF.</p></div><div class="filter-actions"><button class="btn" type="submit">Apply filters</button><a class="btn" href="reports.php">Reset</a></div></div>
<div class="filters">
<div class="field"><label for="from">From date</label><input id="from" type="date" name="from" value="<?= ar_escape($from) ?>"></div>
<div class="field"><label for="to">To date</label><input id="to" type="date" name="to" value="<?= ar_escape($to) ?>"></div>
<div class="field"><label for="role">Account role</label><select id="role" name="role"><?php foreach (['All','User','Admin','Manager','Authenticator'] as $v): ?><option value="<?= ar_escape($v) ?>" <?= $role===$v?'selected':'' ?>><?= ar_escape($v) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="account_status">Account status</label><select id="account_status" name="account_status"><?php foreach (['All','Active','Inactive','Suspended'] as $v): ?><option value="<?= ar_escape($v) ?>" <?= $accountStatus===$v?'selected':'' ?>><?= ar_escape($v) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="profile_verification">Profile verification</label><select id="profile_verification" name="profile_verification"><?php foreach (['All','Pending','Verified','Rejected','No profile'] as $v): ?><option value="<?= ar_escape($v) ?>" <?= $profileVerification===$v?'selected':'' ?>><?= ar_escape($v) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="booking_status">Booking status</label><select id="booking_status" name="booking_status"><?php foreach (['All','Pending','Confirmed','Completed','Cancelled'] as $v): ?><option value="<?= ar_escape($v) ?>" <?= $bookingStatus===$v?'selected':'' ?>><?= ar_escape($v) ?></option><?php endforeach; ?></select></div>
<div class="field"><label for="staff_role">Staff audit role</label><select id="staff_role" name="staff_role"><?php foreach (['All','Manager','Authenticator','Admin'] as $v): ?><option value="<?= ar_escape($v) ?>" <?= $staffRole===$v?'selected':'' ?>><?= ar_escape($v) ?></option><?php endforeach; ?></select></div>
<div class="field search"><label for="q">Search name, email, phone, booking/profile ID or activity</label><input id="q" name="q" value="<?= ar_escape($search) ?>" placeholder="Type keyword or ID"></div>
<div class="field"><label for="limit">Rows per section</label><select id="limit" name="limit"><?php foreach ([25,50,100,200] as $v): ?><option value="<?= $v ?>" <?= $limit===$v?'selected':'' ?>><?= $v ?> rows</option><?php endforeach; ?></select></div>
</div><div style="height:1px;background:var(--line);margin:17px 0"></div><div class="panel-heading"><div><h2>Include in PDF / screen report</h2><p class="sub">Uncheck any section you do not need.</p></div><div class="filter-actions"><button class="btn" type="button" id="selectAll">Select all</button><button class="btn" type="button" id="selectNone">Clear all</button></div></div><div class="checks"><?php foreach ($sectionNames as $key=>$name): ?><label class="check"><input type="checkbox" name="sections[]" value="<?= ar_escape($key) ?>" <?= in_array($key,$sections,true)?'checked':'' ?>><span><strong><?= ar_escape($name) ?></strong><small><?= ['overview'=>'KPIs and financial summary','accounts'=>'Registration and verification state','bookings'=>'Status, customer, manager and value','manager_activity'=>'Actions, packages and booking audit','verification'=>'Verified/rejected profile actions','staff_messages'=>'Staff-to-admin communication trail'][$key] ?></small></span></label><?php endforeach; ?></div>
</form>
<?php if (in_array('overview',$sections,true)): ?><section class="panel"><div class="panel-heading"><div><div class="section-title"><span class="section-dot"></span><h2>Executive overview</h2></div><p class="sub">Current platform snapshot and activity within the selected date range; leave dates blank to include all dates.</p></div><span class="section-count">20 indicators</span></div><div class="metrics"><?php foreach ($metrics as [$label,$value,$kind]): ?><article class="metric"><span><?= ar_escape($label) ?></span><strong><?= $kind==='money'?ar_escape(ar_money($value)):number_format((float)$value) ?></strong><small><?= $label==='Total booking of all time'?'All-time total':(in_array($kind,['snapshot'],true)?'Current snapshot':($from==='' && $to===''?'All dates': 'Selected date range')) ?></small></article><?php endforeach; ?></div><p class="footnote">Booking value represents the stored booking total, not a verified payment-received ledger. Removed bookings are excluded from booking totals.</p></section><?php endif; ?>
<?php if (in_array('accounts',$sections,true)): ?><section class="panel"><div class="panel-heading"><div><div class="section-title"><span class="section-dot"></span><h2>Account &amp; profile register</h2></div><p class="sub">Accounts registered during the selected dates, with current status and linked profile verification.</p></div><div class="table-actions no-print"><span class="section-count"><?= count($userRows) ?> rows shown · max <?= $limit ?></span><a class="btn" href="<?= ar_escape($csvUrl('accounts')) ?>">Export CSV</a></div></div><?php if ($userRows): ?><div class="table-wrap"><table><thead><tr><th>No.</th><th>User ID</th><th>Registered</th><th>Name</th><th>Email</th><th>Mobile</th><th>Role</th><th>Account status</th><th>Profile ID</th><th>Verification</th></tr></thead><tbody><?php foreach ($userRows as $rowIndex => $r): ?><tr><td><?= $rowIndex + 1 ?></td><td><?= (int)$r['user_id'] ?></td><td><?= ar_escape($r['created_at']) ?></td><td><?= ar_escape(trim($r['first_name'].' '.$r['last_name'])) ?></td><td><?= ar_escape($r['email']) ?></td><td><?= ar_escape($r['mobile']) ?></td><td><?= ar_escape($r['role']) ?></td><td><span class="pill <?= $r['account_status']==='Suspended'?'bad':($r['account_status']==='Inactive'?'warn':'') ?>"><?= ar_escape($r['account_status']) ?></span></td><td><?= $r['profile_id']===null?'—':(int)$r['profile_id'] ?></td><td><?= $r['verification_status']?'<span class="pill '.($r['verification_status']==='Rejected'?'bad':($r['verification_status']==='Pending'?'warn':'')).'">'.ar_escape($r['verification_status']).'</span>':'No profile' ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No accounts match these filters.</div><?php endif; ?></section><?php endif; ?>
<?php if (in_array('bookings',$sections,true)): ?><section class="panel"><div class="panel-heading"><div><div class="section-title"><span class="section-dot"></span><h2>Booking &amp; value register</h2></div><p class="sub">Booking records and stored total values for the selected date range.</p></div><div class="table-actions no-print"><span class="section-count"><?= count($bookingRows) ?> rows shown · max <?= $limit ?></span><a class="btn" href="<?= ar_escape($csvUrl('bookings')) ?>">Export CSV</a></div></div><?php if ($bookingRows): ?><div class="table-wrap"><table><thead><tr><th>No.</th><th>Booking ID</th><th>Date</th><th>Customer</th><th>Email</th><th>Manager</th><th>Status</th><th>Total value</th></tr></thead><tbody><?php foreach ($bookingRows as $rowIndex => $r): ?><tr><td><?= $rowIndex + 1 ?></td><td>#<?= (int)$r['booking_id'] ?></td><td><?= ar_escape($r['booking_date']) ?></td><td><?= ar_escape(trim($r['customer_name'])) ?> <span class="muted">(#<?= (int)$r['user_id'] ?>)</span></td><td><?= ar_escape($r['email']??'') ?></td><td><?= ar_escape(trim($r['manager_name']??'') ?: ($r['manager_id']?'Staff #'.(int)$r['manager_id']:'Unassigned')) ?></td><td><span class="pill <?= $r['booking_status']==='Cancelled'?'bad':($r['booking_status']==='Pending'?'warn':'') ?>"><?= ar_escape($r['booking_status']) ?></span></td><td><strong><?= ar_escape(ar_money($r['total_price'])) ?></strong></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No bookings match these filters.</div><?php endif; ?></section><?php endif; ?>
<?php if (in_array('manager_activity',$sections,true)): ?><section class="panel"><div class="panel-heading"><div><div class="section-title"><span class="section-dot"></span><h2>Manager activity audit</h2></div><p class="sub">Recent manager actions and the recorded booking/provider/value context.</p></div><div class="table-actions no-print"><span class="section-count"><?= count($managerRows) ?> rows shown · max <?= $limit ?></span><a class="btn" href="<?= ar_escape($csvUrl('manager_activity')) ?>">Export CSV</a></div></div><?php if ($managerRows): ?><div class="table-wrap"><table><thead><tr><th>No.</th><th>Time</th><th>Manager</th><th>Action</th><th>Booking</th><th>Provider</th><th>Amount</th><th>Details</th></tr></thead><tbody><?php foreach ($managerRows as $rowIndex => $r): ?><tr><td><?= $rowIndex + 1 ?></td><td><?= ar_escape($r['created_at']) ?></td><td><?= ar_escape($r['manager_name']) ?></td><td><?= ar_escape($r['action_type']) ?></td><td><?= $r['booking_id']?(int)$r['booking_id']:'—' ?></td><td><?= $r['provider_id']?(int)$r['provider_id']:'—' ?></td><td><?= ar_escape(ar_money($r['amount'])) ?></td><td><?= ar_escape($r['details']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No manager activity matches these filters.</div><?php endif; ?></section><?php endif; ?>
<?php if (in_array('verification',$sections,true)): ?><section class="panel"><div class="panel-heading"><div><div class="section-title"><span class="section-dot"></span><h2>Authenticator verification audit</h2></div><p class="sub">Verified/rejected actions with profile ID, staff identity and remarks.</p></div><div class="table-actions no-print"><span class="section-count"><?= count($verifyRows) ?> rows shown · max <?= $limit ?></span><a class="btn" href="<?= ar_escape($csvUrl('verification')) ?>">Export CSV</a></div></div><?php if ($verifyRows): ?><div class="table-wrap"><table><thead><tr><th>No.</th><th>Time</th><th>Authenticator</th><th>Staff ID</th><th>Profile ID</th><th>Action</th><th>Remarks</th></tr></thead><tbody><?php foreach ($verifyRows as $rowIndex => $r): ?><tr><td><?= $rowIndex + 1 ?></td><td><?= ar_escape($r['action_at']) ?></td><td><?= ar_escape(trim($r['authenticator_name']) ?: 'Unknown staff') ?></td><td><?= (int)$r['authenticator_id'] ?></td><td><?= (int)$r['profile_id'] ?></td><td><span class="pill <?= $r['action']==='Rejected'?'bad':'' ?>"><?= ar_escape($r['action']) ?></span></td><td><?= ar_escape($r['remarks']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No verification actions match these filters.</div><?php endif; ?></section><?php endif; ?>
<?php if (in_array('staff_messages',$sections,true)): ?><section class="panel"><div class="panel-heading"><div><div class="section-title"><span class="section-dot"></span><h2>Staff communication audit</h2></div><p class="sub">Staff/admin message records in the selected period. Message text is included in this restricted admin report.</p></div><div class="table-actions no-print"><span class="section-count"><?= count($messageRows) ?> rows shown · max <?= $limit ?></span><a class="btn" href="<?= ar_escape($csvUrl('staff_messages')) ?>">Export CSV</a></div></div><?php if ($messageRows): ?><div class="table-wrap"><table><thead><tr><th>No.</th><th>Time</th><th>Sender</th><th>Recipient</th><th>Status</th><th>Message</th><th>Read at</th></tr></thead><tbody><?php foreach ($messageRows as $rowIndex => $r): ?><tr><td><?= $rowIndex + 1 ?></td><td><?= ar_escape($r['created_at']) ?></td><td><?= ar_escape(trim($r['sender_name']??'') ?: $r['sender_role']) ?> <span class="muted">(<?= ar_escape($r['sender_role']) ?>)</span></td><td><?= ar_escape(trim($r['recipient_name']??'') ?: $r['recipient_role']) ?> <span class="muted">(<?= ar_escape($r['recipient_role']) ?>)</span></td><td><span class="pill <?= $r['status']==='Unread'?'warn':'' ?>"><?= ar_escape($r['status']) ?></span></td><td><?= ar_escape($r['message']) ?></td><td><?= ar_escape($r['read_at']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">No staff messages match these filters.</div><?php endif; ?></section><?php endif; ?>
<footer class="footnote">Confidential · For authorized Admin use only. Account status and profile verification shown in the register are current values; date filters select registration/activity dates where indicated.</footer>
</main><script>
(function(){const form=document.getElementById('reportFilters');if(!form)return;const boxes=()=>Array.from(form.querySelectorAll('input[name="sections[]"]'));document.getElementById('selectAll')?.addEventListener('click',()=>boxes().forEach(b=>b.checked=true));document.getElementById('selectNone')?.addEventListener('click',()=>boxes().forEach(b=>b.checked=false));form.addEventListener('submit',()=>{if(!boxes().some(b=>b.checked)){const overview=form.querySelector('input[name="sections[]"][value="overview"]');if(overview)overview.checked=true;}});})();
</script></body></html>
